package db

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// BackupResult contains the file paths generated by an online atomic backup.
type BackupResult struct {
	AppBackupPath   string
	AuditBackupPath string
}

// Backup performs online atomic SQLite backups of both app and audit databases using VACUUM INTO.
func (s *Store) Backup(ctx context.Context, outDir string) (BackupResult, error) {
	if outDir == "" {
		return BackupResult{}, errors.New("backup output directory must not be empty")
	}
	absOut, err := filepath.Abs(filepath.Clean(outDir))
	if err != nil {
		return BackupResult{}, fmt.Errorf("resolve backup dir: %w", err)
	}
	if err := os.MkdirAll(absOut, 0o750); err != nil {
		return BackupResult{}, fmt.Errorf("create backup dir: %w", err)
	}

	stamp := time.Now().UTC().Format("20060102-150405.000000000")
	appTarget := filepath.Join(absOut, fmt.Sprintf("app-%s.sqlite", stamp))
	auditTarget := filepath.Join(absOut, fmt.Sprintf("audit-%s.sqlite", stamp))

	if err := vacuumInto(ctx, s.AppWrite, appTarget); err != nil {
		return BackupResult{}, fmt.Errorf("backup app db: %w", err)
	}
	if err := vacuumInto(ctx, s.Audit, auditTarget); err != nil {
		return BackupResult{}, fmt.Errorf("backup audit db: %w", err)
	}

	return BackupResult{
		AppBackupPath:   appTarget,
		AuditBackupPath: auditTarget,
	}, nil
}

func vacuumInto(ctx context.Context, db *sql.DB, targetPath string) error {
	if _, err := os.Stat(targetPath); err == nil {
		return fmt.Errorf("backup target already exists: %s", targetPath)
	}
	if _, err := db.ExecContext(ctx, `VACUUM INTO ?`, targetPath); err != nil {
		return err
	}
	return os.Chmod(targetPath, 0o640)
}
